func TestEnumRegistryProvider(t *testing.T) {
	t.Run("NewFromString_ecr", func(t *testing.T) {
		t.Parallel()
		val, err := NewRegistryProviderFromString("ecr")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, RegistryProvider("ecr"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewRegistryProviderFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewRegistryProviderFromString("ecr")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

